// <auto-generated>
// Campground.Shared — compiled into each Campground plugin as internal code.
// Edit it in AHouseOfBards/Campground-Coordination/shared, never inside a plugin.
// </auto-generated>
#nullable enable

using System;
using System.Collections.Generic;
using System.Linq;
using Campground.Shared.Registry;
using MediaBrowser.Common.Net;
using MediaBrowser.Controller.Configuration;
using Microsoft.AspNetCore.Http;

namespace Campground.Shared.Network
{
    /// <summary>Reads <see cref="NetworkSettings"/> from Jellyfin, and classifies live requests.</summary>
    internal static class JellyfinNetworkSettings
    {
        private const string VpnSection = "network.vpn";

        /// <summary>Jellyfin's network settings plus the admin-entered VPN ranges shared by every plugin.</summary>
        internal static NetworkSettings Read(IServerConfigurationManager serverConfig)
        {
            try
            {
                var n = serverConfig.GetNetworkConfiguration();
                return new NetworkSettings(
                    n.LocalNetworkSubnets ?? Array.Empty<string>(),
                    n.KnownProxies ?? Array.Empty<string>(),
                    VpnRanges,
                    NormalizeBaseUrl(n.BaseUrl),
                    n.RequireHttps,
                    n.EnableHttps,
                    n.PublishedServerUriBySubnet ?? Array.Empty<string>());
            }
            catch (Exception)
            {
                return new NetworkSettings(Array.Empty<string>(), Array.Empty<string>(), VpnRanges, string.Empty, false, false, Array.Empty<string>());
            }
        }

        /// <summary>
        /// VPN ranges (CIDR) the admin entered in any Campground plugin. Stored in the registry so every plugin
        /// agrees; the plugin that owns the setting calls <see cref="SetVpnRanges"/> at startup and on save.
        /// </summary>
        internal static IReadOnlyList<string> VpnRanges
            => CampgroundRegistry.Section(VpnSection).TryGetValue("ranges", out var v) && v is string[] a ? a : Array.Empty<string>();

        /// <summary>Publishes the VPN ranges for every plugin.</summary>
        internal static void SetVpnRanges(IEnumerable<string> ranges)
            => CampgroundRegistry.Section(VpnSection)["ranges"] = ranges.Where(r => !string.IsNullOrWhiteSpace(r)).Select(r => r.Trim()).ToArray();

        /// <summary>Classifies an HTTP request.</summary>
        internal static Classification Classify(HttpContext context, IServerConfigurationManager serverConfig)
            => NetworkClassifier.Classify(
                context.Connection.RemoteIpAddress,
                context.Request.Headers["X-Forwarded-For"].ToString(),
                context.Request.Headers["X-Forwarded-Proto"].ToString(),
                Read(serverConfig));

        /// <summary>Base URL as Jellyfin normalises it: leading slash, no trailing one, empty when unset.</summary>
        internal static string NormalizeBaseUrl(string? baseUrl)
        {
            var trimmed = (baseUrl ?? string.Empty).Trim().Trim('/');
            return trimmed.Length == 0 ? string.Empty : "/" + trimmed;
        }
    }
}
